namespace fs=std::filesystem;using J=nlohmann::json;
J rows=J::array();unsigned failures=0;void Check(bool x,const char*n){rows.push_back({{"name",n},{"passed",x}});failures+=!x;std::cout<<(x?"PASS ":"FAIL ")<<n<<'\n';}
void Need(bool x,const char*n){Check(x,n);if(!x)throw std::runtime_error(n);}
struct Gate{std::mutex mutex;std::condition_variable cv;bool reached=false,open=false,claimed=false;unsigned stale=0;void Release(){std::lock_guard<std::mutex>l(mutex);open=true;cv.notify_all();}};
int main(int argc,char**argv){if(argc!=2)return 2;fs::path out=argv[1];if(fs::exists(out))return 3;fs::create_directories(out);EngineHost host;Gate gate;std::string error;try{
 Project p;Need(Project::CreateNew((out/"project").string(),"Skeletal replacement audit",p,error),"ordinary owned project");auto path=fs::path(p.AssetsDir())/"rig.glb";fs::copy_file("projects/animation_demo/Assets/models/bend_bar.glb",path);Need(host.Init("M78 skeletal replacement",320,240,false,error),"actual GL/async host");host.OpenProjectAssets(p.RootDir(),p.AssetsDir());auto& rm=host.Resources();AssetRecord model;Need(host.Assets().Track(path.string(),model,error),"ordinary skeletal asset registration");Need(host.Jobs().WorkerCount()>=2,"independent late/new completion workers available");rm.AddRef(model.id);
 auto pumpUntil=[&](auto predicate){auto end=std::chrono::steady_clock::now()+std::chrono::seconds(10);while(!predicate()&&std::chrono::steady_clock::now()<end){rm.Pump();std::this_thread::sleep_for(std::chrono::milliseconds(1));}return predicate();};
 rm.RequestMesh(model.id);Need(pumpUntil([&]{return rm.StateOf(model.id)==ResourceState::Ready;}),"initial real skeletal asset ready");auto first=rm.TryGetSkeletal(model.id);auto mesh=rm.TryGetMesh(model.id);Need(bool(first)&&first->skeleton.names[0]=="Root","initial immutable skeleton identity");Scene fixture;Need(LoadSceneFromFile("projects/ragdoll_demo/Scenes/main.judas",fixture,error),"ordinary authored articulation fixture");Scene scene;auto&a=scene.CreateObject("one");auto aid=a.id;a.render=SceneRenderComponent{};a.render->shape=SceneShape::Mesh;a.render->meshAsset=model.id;a.animation=SceneAnimationComponent{};a.animation->playOnStart=false;a.ragdoll=fixture.Find(10)->ragdoll;a.ragdoll->playOnStart=false;auto b=a;b.id=scene.CreateObject("two").id;*scene.Find(b.id)=b;auto bid=b.id;auto socket=scene.CreateObject("visual socket").id;RuntimeWorld world;Need(world.Build(scene,&rm,error,&p.Settings().classification),"normal shared-asset world");world.UpdateAnimations(.1f);Need(world.RuntimeAnimation(aid)->asset==first&&world.RuntimeAnimation(bid)->asset==first,"two actual runtime consumers share first asset");
 SceneSocketComponent attachment;attachment.target=aid;attachment.joint="Root";attachment.offset.position={.13f,.17f,.19f};Need(world.SetSocket(socket,attachment,false,error),"socket installed through normal identity validation");world.UpdateSockets();SceneTransform joint;Need(world.JointPose(aid,"Root","world",1,joint),"initial resolved joint available");Check(glm::length(world.RuntimeDefinition(socket)->transform.position-(joint.position+joint.rotation*(joint.scale*attachment.offset.position)))<1e-5,"socket consumes actual final joint pose");FullBodyIKSettings ik;ik.bodyRoot="Root";ik.chains.push_back({"arm",{"Root","Elbow","Tip"}});Need(world.ConfigureFullBodyIK(aid,ik,error),"shared IK configured on old hierarchy");Need(world.EnterRagdoll(aid,error),"physical articulation uses actual old rig");auto oldBone=world.RuntimeBody(world.RagdollBody(aid,"Root"));Need(oldBone.IsValid(),"old mapped physical body exists");const auto socketBefore=world.RuntimeDefinition(socket)->transform;
 rm.SetTrace([&](const ResourceTraceEvent&e){if(e.asset!=model.id)return;std::unique_lock<std::mutex>l(gate.mutex);if(e.point==ResourceTracePoint::StaleDiscarded)++gate.stale;if(e.point==ResourceTracePoint::DecodeEnd&&!gate.claimed){gate.claimed=true;gate.reached=true;gate.cv.notify_all();gate.cv.wait(l,[&]{return gate.open;});}});
 rm.Invalidate(model.id);rm.RequestMesh(model.id);Need(pumpUntil([&]{std::lock_guard<std::mutex>l(gate.mutex);return gate.reached;}),"real old decode held before publication");world.UpdateAnimations(0);Check(!world.RuntimeAnimation(aid)->asset&&!world.RuntimeAnimation(bid)->asset,"invalidated in-flight asset cannot remain resolved on either consumer");world.UpdateRagdolls(0);world.UpdateSockets();Check(!world.RagdollActive(aid)&&!world.Physics().IsBodyEnabled(oldBone),"invalidated skeleton retires physical authority and old body handles");Check(!world.SetFullBodyIKTargets(aid,{},error),"pending skeleton cannot accept old IK target mapping");Check(world.RuntimeDefinition(socket)->transform.position==socketBefore.position,"unresolved socket retains last transform rather than fabricating a joint");MeshData retired;Check(!host.GetRenderer().ReadMeshForDiagnostics(mesh,retired),"invalidation actually retires old GPU handle");
 std::ifstream file(path,std::ios::binary);std::string bytes((std::istreambuf_iterator<char>(file)),{});file.close();auto at=bytes.find("\"Root\"");Need(at!=std::string::npos&&bytes.find("\"Root\"",at+6)==std::string::npos,"single same-length authored identity replacement fixture");bytes.replace(at+1,4,"Base");std::ofstream(path,std::ios::binary).write(bytes.data(),bytes.size());MeshData independentlyImported;Need(LoadModelMesh(path.string(),independentlyImported,error)&&independentlyImported.skeletal->skeleton.names[0]=="Base","commodity importer independently confirms replacement content");rm.Invalidate(model.id);rm.RequestMesh(model.id);Need(pumpUntil([&]{return rm.StateOf(model.id)==ResourceState::Ready;}),"new replacement publishes while old decode remains held");auto newer=rm.TryGetSkeletal(model.id);Need(newer&&newer!=first&&newer->skeleton.names[0]=="Base","new immutable skeleton—not cached old source—published");world.UpdateAnimations(0);Check(world.RuntimeAnimation(aid)->asset==newer&&world.RuntimeAnimation(bid)->asset==newer,"all actual consumers resolve new immutable asset");SceneTransform pose;Check(!world.JointPose(aid,"Root","model",1,pose)&&world.JointPose(aid,"Base","model",1,pose),"resolved joint identity follows actual replacement");world.UpdateSockets();Check(world.RuntimeDefinition(socket)->transform.position==socketBefore.position,"removed socket identity does not attach to a replacement index");Check(world.RuntimeAnimation(aid)->fullBodyIK&&!world.RuntimeAnimation(aid)->fullBodyIK->prepared,"old IK identity cannot silently remap to renamed root");Check(!world.EnterRagdoll(aid,error)&&!world.RagdollActive(aid),"incompatible authored ragdoll mapping rejects new skeleton");attachment.joint="Base";Need(world.SetSocket(socket,attachment,false,error),"explicit new socket key can bind replacement");world.UpdateSockets();Need(world.JointPose(aid,"Base","world",1,joint),"replacement resolved joint available");Check(glm::length(world.RuntimeDefinition(socket)->transform.position-(joint.position+joint.rotation*(joint.scale*attachment.offset.position)))<1e-5,"rebound socket follows new final pose");auto newestMesh=rm.TryGetMesh(model.id);gate.Release();host.Jobs().WaitAll();rm.Pump();Check(rm.TryGetSkeletal(model.id)==newer&&rm.TryGetMesh(model.id).id==newestMesh.id&&gate.stale>0,"late old skeletal completion discarded without overwriting new resource");Check(first->skeleton.names[0]=="Root","retained immutable old reference is not mutated in place");
 rm.SetTrace({});std::ofstream(path,std::ios::binary)<<"invalid glb";rm.Invalidate(model.id);rm.RequestMesh(model.id);Need(pumpUntil([&]{return rm.StateOf(model.id)==ResourceState::Failed;}),"malformed replacement visibly fails decode");world.UpdateAnimations(0);Check(!rm.TryGetSkeletal(model.id)&&!world.RuntimeAnimation(aid)->asset&&!world.RuntimeAnimation(bid)->asset,"failed replacement cannot silently retain a live old skeleton");Check(!rm.ErrorOf(model.id).empty(),"malformed replacement diagnostic retained");fs::copy_file("projects/animation_demo/Assets/models/bend_bar.glb",path,fs::copy_options::overwrite_existing);rm.Invalidate(model.id);rm.RequestMesh(model.id);Need(pumpUntil([&]{return rm.StateOf(model.id)==ResourceState::Ready;}),"valid source recovers after failed replacement");world.UpdateAnimations(0);Check(world.JointPose(aid,"Root","model",1,pose)&&world.RuntimeAnimation(aid)->asset==world.RuntimeAnimation(bid)->asset,"recovered source resolves both live consumers normally");Need(world.EnterRagdoll(aid,error),"recovered original mapping can reenter physical authority");auto recoveredBone=world.RuntimeBody(world.RagdollBody(aid,"Root"));Check(recoveredBone.IsValid()&&recoveredBone.id!=oldBone.id,"recovered articulation does not alias retired body generation");world.Destroy();Check(!world.RuntimeDefinition(aid)&&!world.RagdollActive(aid),"world teardown retires animation and articulation ownership");rm.ReleaseRef(model.id);rm.Release(model.id);rm.Pump();Check(rm.Stats().bytesResident==0,"teardown retires all fixture CPU/GPU residency");
 }catch(const std::exception&e){Check(false,e.what());}gate.Release();host.Shutdown();std::ofstream(out/"RESULT.json")<<J{{"checks",rows},{"failures",failures},{"scope","Actual async GLB publication with sockets, shared IK, physical articulation, incompatible identity rejection and teardown; not all asset families or editor gestures"}}.dump(2)<<'\n';std::cout<<"SUMMARY "<<rows.size()<<" checks / "<<failures<<" failures\n";return failures?1:0;}
